<?php declare(strict_types=1); namespace App\People\Infrastructure\Persistence\DBAL; use App\People\Domain\Model\Person; use App\People\Domain\Repository\PersonRepository; use App\People\Domain\ValueObject\PersonId; use Doctrine\DBAL\Connection; final readonly class DbalPersonRepository implements PersonRepository {public function __construct(private Connection $connection,private PersonMapper $mapper){} public function save(Person $p):void{$d=$this->mapper->toRow($p);$exists=$this->connection->fetchOne('SELECT 1 FROM people_persons WHERE id=:id',['id'=>$p->id()->toString()]);if($exists){unset($d['id']);$this->connection->update('people_persons',$d,['id'=>$p->id()->toString()]);}else{$this->connection->insert('people_persons',$d);}} public function findById(PersonId $id):?Person{$r=$this->connection->fetchAssociative('SELECT * FROM people_persons WHERE id=:id',['id'=>$id->toString()]);return $r===false?null:$this->mapper->toDomain($r);} public function exists(PersonId $id):bool{return (bool)$this->connection->fetchOne('SELECT 1 FROM people_persons WHERE id=:id',['id'=>$id->toString()]);} public function findAll():array{$rows=$this->connection->fetchAllAssociative('SELECT * FROM people_persons ORDER BY last_name,first_name');return array_map(fn(array $r):Person=>$this->mapper->toDomain($r),$rows);}}
